typedef unsigned int u_int;

struct sceIpuRGB32
{
    u_int value;
};

struct sceMpeg
{
    int width;
    int height;
    int frameCount;
    char reserved[0x3c];
};

struct ViBuf
{
    char data[1];
};

struct VideoDec
{
    sceMpeg mpeg;
    ViBuf vibuf;
    u_int state;
};

struct VoData
{
    unsigned char v[720 * 576 * 4];
};

struct VoTag
{
    int status;
    int dummy[15];
    u_int v[2][155584];
};

struct VoBuf
{
    VoData *data;
    VoTag *tag;
    volatile int write;
    volatile int count;
    int size;
};

static VoBuf voBuf;

extern "C" int sceMpegIsEnd(sceMpeg *);
extern "C" int sceMpegGetPicture(sceMpeg *, sceIpuRGB32 *, int);
extern "C" int sceMpegReset(sceMpeg *);
extern "C" int RotateThreadReadyQueue(int);

static u_int videoDecGetState(VideoDec *);
static VoData *voBufGetData(VoBuf *);
static void voBufIncCount(VoBuf *);
static void setImageTag(u_int *, void *, int, int, int);

inline void nvlPrintf(const char *, ...)
{
}

static int decBs0( VideoDec* vd )
{
    VoData      *voData;
    sceIpuRGB32 *rgb32;
    int         ret, status = 1;
    sceMpeg     *mp = &vd->mpeg;

    while( !sceMpegIsEnd(&vd->mpeg) )
    {
        if( videoDecGetState(vd) == 1 )
        {
            status = -1;
            nvlPrintf("decode thread: aborted\n");
            break;
        }
        while( !(voData = voBufGetData(&voBuf)) )
        {
            RotateThreadReadyQueue( 50 );
        }
        rgb32 = (sceIpuRGB32*)voData->v;
        ret = sceMpegGetPicture( mp, rgb32, 720 / 16 * 576 / 16 );
        if( ret < 0 )
        {
            nvlPrintf("sceMpegGetPicture() decode error");
        }
        if( mp->frameCount == 0 )
        {
            int i, image_w, image_h;

            image_w = mp->width;
            image_h = mp->height;
            for( i = 0; i < voBuf.size; i++ )
            {
                setImageTag( voBuf.tag[i].v[0], voBuf.data[i].v, 0, image_w, image_h );
                setImageTag( voBuf.tag[i].v[1], voBuf.data[i].v, 1, image_w, image_h );
            }
        }
        voBufIncCount( &voBuf );
        RotateThreadReadyQueue( 50 );
    }
    sceMpegReset( mp );
    return status;
}
